parameters.jsCode:
const resposta = $input.item.json;
const origem = $("Lotes para o Gemini").item.json;

const texto =
  (resposta &&
    resposta.candidates &&
    resposta.candidates[0] &&
    resposta.candidates[0].content &&
    resposta.candidates[0].content.parts &&
    resposta.candidates[0].content.parts[0] &&
    resposta.candidates[0].content.parts[0].text) ||
  "";

// Diferenca proposital em relacao ao receipt-ocr-classification: la o parser
// lanca excecao quando nao acha o bloco <expense>, porque a execucao trata uma
// mensagem so e falhar avisa o usuario. Aqui uma excecao derrubaria o lote
// inteiro e as outras transacoes junto. Entao resposta ruim vira uma evidencia
// INDETERMINADA em revisao humana, que e o destino conservador correto.
//
// Resposta vazia nao e caso hipotetico: o gemini-3-flash-preview nao permite
// desligar thinking, e quando o thinking consome o orcamento de saida o texto
// volta em branco (ver AGENTS.md).
function semClassificacao(motivo) {
  return {
    categoria: "OUTROS",
    deducibilidade: "INDETERMINADO",
    justificativa_deducibilidade: motivo,
    confidence_score: 0.2,
    requer_revisao_humana: true,
    motivos_revisao: [motivo],
    possui_indicio_tuss_cbhpm: false,
    codigos_medicos_identificados: [],
    termos_auditoria_identificados: [],
    falha_ia: motivo,
  };
}

let classificacao;

if (!texto.trim()) {
  classificacao = semClassificacao("A IA devolveu resposta vazia para esta transacao");
} else {
  const limpo = texto
    .replace(/\\n/g, "\n")
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, "\\");
  const bloco = limpo.match(/<expense>([\s\S]*?)<\/expense>/);

  if (!bloco) {
    classificacao = semClassificacao("A resposta da IA nao trouxe o bloco <expense>");
  } else {
    try {
      classificacao = JSON.parse(bloco[1].trim());
    } catch (e) {
      classificacao = semClassificacao("JSON invalido dentro do bloco <expense>: " + e.message);
    }
  }
}

return {
  json: {
    ...origem,
    system_prompt: undefined,
    entrada_ia: undefined,
    fonte_classificacao: "GEMINI",
    classificacao,
  },
};

// Ramo que nao passa pela IA: a categoria da Pluggy ja basta para cravar
// NAO_DEDUTIVEL. Monta a mesma forma de saida do ramo do Gemini para que
// "Montar Evidencias" trate os dois sem saber de onde vieram.
//
// confidence_score alto (0.95) e requer_revisao_humana false sao deliberados:
// nao ha ambiguidade a resolver. O que sustenta o numero e a categoria do
// agregador, e a justificativa registra qual regra decidiu — a trilha fica
// auditavel sem precisar reprocessar nada.
return $input.all().map((item) => {
  const t = item.json;
  const preFiltro = t.pre_filtro || {};

  return {
    json: {
      ...t,
      system_prompt: undefined,
      entrada_ia: undefined,
      fonte_classificacao: "PRE_FILTRO",
      classificacao: {
        categoria: preFiltro.categoria || "OUTROS",
        deducibilidade: "NAO_DEDUTIVEL",
        justificativa_deducibilidade:
          "Classificado sem IA pela categoria do agregador (" +
          (t.categoria_pluggy || "sem rotulo") +
          " / " +
          (t.categoria_pluggy_id || "sem id") +
          "): " +
          (preFiltro.motivo || "categoria nunca dedutivel no IRPF"),
        confidence_score: 0.95,
        requer_revisao_humana: false,
        motivos_revisao: [],
        possui_indicio_tuss_cbhpm: false,
        codigos_medicos_identificados: [],
        termos_auditoria_identificados: [],
      },
    },
  };
});

// Junta os dois ramos numa lista unica de linhas prontas para o PostgREST.
// Sai UM item so, com o array inteiro em `linhas`: o insert seguinte manda
// tudo num POST so, em vez de uma requisicao por transacao.
const itens = $input.all().map((i) => i.json).filter((t) => t && t.transaction_id);

const CATEGORIAS_VALIDAS = new Set([
  "SAUDE", "EDUCACAO", "ALIMENTACAO", "TRANSPORTE", "MORADIA", "ESCRITORIO",
  "EQUIPAMENTOS", "SOFTWARE", "INTERNET_TELEFONIA", "SERVICOS_PROFISSIONAIS",
  "IMPOSTOS_TAXAS", "OUTROS",
]);
const DEDUCIBILIDADES_VALIDAS = new Set([
  "DEDUTIVEL", "NAO_DEDUTIVEL", "PARCIALMENTE_DEDUTIVEL", "INDETERMINADO",
]);

const linhas = itens.map((t) => {
  const c = t.classificacao || {};

  // categoria e deducibilidade sao enums no Postgres: valor fora da lista
  // derruba o insert do lote inteiro com 22P02. O ramo do pre-filtro sempre
  // manda valor valido; o ramo do Gemini nao tem essa garantia.
  const categoria = CATEGORIAS_VALIDAS.has(c.categoria) ? c.categoria : "OUTROS";
  const deducibilidade = DEDUCIBILIDADES_VALIDAS.has(c.deducibilidade)
    ? c.deducibilidade
    : "INDETERMINADO";

  const categoriaTrocada = c.categoria && categoria !== c.categoria;
  const requerRevisao = c.requer_revisao_humana === false && !categoriaTrocada ? false : true;

  const confianca = Number(c.confidence_score);

  return {
    usuario_id: t.usuario_id,
    // Sem sessao_whatsapp_id de proposito: nao existe conversa de WhatsApp
    // nesta origem, a transacao veio do banco.
    origem: "OPEN_FINANCE",
    status: requerRevisao ? "REVISAO_HUMANA" : "APROVADO_AUTOMATICAMENTE",
    descricao: t.descricao || "Transacao bancaria",
    estabelecimento: t.estabelecimento || c.estabelecimento || null,
    documento_prestador: t.documento_prestador || c.documento_prestador || null,
    // valor e data vem do extrato, nunca da IA: o banco e a fonte de verdade e
    // o modelo so foi chamado para classificar. Deixar o numero do LLM entrar
    // aqui abriria espaco para valor alucinado num dossie que vai para a Receita.
    data_despesa: t.data_despesa,
    valor: Math.round((Number(t.valor) || 0) * 100) / 100,
    categoria,
    deducibilidade,
    justificativa_deducibilidade: c.justificativa_deducibilidade || null,
    confidence_score: Number.isFinite(confianca) ? Math.min(Math.max(confianca, 0), 1) : 0,
    requer_revisao_humana: requerRevisao,
    possui_indicio_tuss_cbhpm: c.possui_indicio_tuss_cbhpm === true,
    codigos_medicos_identificados: Array.isArray(c.codigos_medicos_identificados)
      ? c.codigos_medicos_identificados
      : [],
    termos_auditoria_identificados: Array.isArray(c.termos_auditoria_identificados)
      ? c.termos_auditoria_identificados
      : [],
    dados_open_finance: {
      transaction_id: t.transaction_id,
      item_id: t.item_id,
      account_id: t.account_id,
      conta_nome: t.conta_nome,
      connector_nome: t.connector_nome,
      categoria_pluggy: t.categoria_pluggy,
      categoria_pluggy_id: t.categoria_pluggy_id,
      moeda: t.moeda,
      descricao_original: t.descricao_original,
      sincronizado_desde: t.sincronizado_desde,
      fonte_classificacao: t.fonte_classificacao,
    },
    metadados_ia: {
      fonte: t.fonte_classificacao,
      modelo: t.fonte_classificacao === "GEMINI" ? "gemini-3-flash-preview" : null,
      classificacao: c,
    },
  };
});

const primeiro = itens[0] || {};

return [{
  json: {
    linhas,
    telefone: primeiro.telefone || null,
    connector_nome: primeiro.connector_nome || null,
    sincronizado_desde: primeiro.sincronizado_desde || null,
    total_enviadas: linhas.length,
    total_por_ia: itens.filter((t) => t.fonte_classificacao === "GEMINI").length,
    total_por_prefiltro: itens.filter((t) => t.fonte_classificacao === "PRE_FILTRO").length,
    lote_recebidas: primeiro.lote_recebidas || linhas.length,
    lote_duplicadas: primeiro.lote_duplicadas || 0,
  },
}];

// UMA mensagem por sincronizacao, nunca uma por transacao: numa carga inicial
// de 200 transacoes, mensagem por despesa seria uma enchente no WhatsApp do
// usuario e provavelmente um bloqueio do numero pela Meta.
const contexto = $("Montar Evidencias").first().json;

// Com resolution=ignore-duplicates o PostgREST devolve so as linhas que
// entraram de fato; as que bateram no indice unico somem da representacao.
// Comparar com o que foi enviado da o numero de duplicatas que escaparam do
// pre-filtro (corrida entre dois webhooks do mesmo item, por exemplo).
const gravadas = $input
  .all()
  .map((i) => i.json)
  .reduce((acc, linha) => acc.concat(Array.isArray(linha) ? linha : [linha]), [])
  .filter((l) => l && l.id);

const dedutiveis = gravadas.filter(
  (l) => l.deducibilidade === "DEDUTIVEL" || l.deducibilidade === "PARCIALMENTE_DEDUTIVEL",
).length;
const emRevisao = gravadas.filter((l) => l.requer_revisao_humana === true).length;

const brl = (v) =>
  Number(v || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const totalDedutivel = gravadas
  .filter((l) => l.deducibilidade === "DEDUTIVEL" || l.deducibilidade === "PARCIALMENTE_DEDUTIVEL")
  .reduce((soma, l) => soma + Number(l.valor || 0), 0);

// O texto do periodo sai de sincronizado_desde, que a propria Edge Function
// manda. Nao cravar "ultimos 12 meses" e proposital: a janela inicial hoje e
// JANELA_INICIAL_DIAS = 30 na pluggy-webhook, e sincronizacao incremental cobre
// so alguns dias. Derivando do campo, a frase continua verdadeira se alguem
// mexer nessa constante.
function periodo(desde) {
  if (!desde) return "";
  const ms = Date.now() - new Date(desde + "T00:00:00Z").getTime();
  const dias = Math.round(ms / 86400000);
  if (dias <= 1) return " de hoje";
  if (dias <= 45) return " dos ultimos " + dias + " dias";
  const meses = Math.max(1, Math.round(dias / 30));
  return " dos ultimos " + meses + (meses === 1 ? " mes" : " meses");
}

const banco = contexto.connector_nome ? " " + contexto.connector_nome : "";
const n = gravadas.length;

const partes = [];

if (n === 0) {
  partes.push(
    "Sincronizei sua conta" + banco + " e nao encontrei despesa nova para classificar.",
  );
} else {
  partes.push(
    "Prontinho! Conectei sua conta" +
      banco +
      " e classifiquei " +
      n +
      (n === 1 ? " despesa" : " despesas") +
      periodo(contexto.sincronizado_desde) +
      ".",
  );

  const linhas = [];
  if (dedutiveis > 0) {
    linhas.push(
      "\u{2705} " +
        dedutiveis +
        (dedutiveis === 1 ? " potencialmente dedutivel" : " potencialmente dedutiveis") +
        " (" + brl(totalDedutivel) + ")",
    );
  }
  if (emRevisao > 0) {
    linhas.push(
      "\u{1F50E} " +
        emRevisao +
        (emRevisao === 1 ? " precisa" : " precisam") +
        " de revisao do seu contador",
    );
  }
  const naoDedutiveis = n - dedutiveis - emRevisao;
  if (naoDedutiveis > 0) {
    linhas.push("\u{1F4CC} " + naoDedutiveis + " sem efeito no IRPF");
  }
  if (linhas.length > 0) partes.push(linhas.join("\n"));
}

if (contexto.lote_duplicadas > 0) {
  const d = contexto.lote_duplicadas;
  partes.push(
    "(" + d + (d === 1 ? " ja estava registrada" : " ja estavam registradas") + ", entao pulei)",
  );
}

partes.push("Manda *resumo* para ver o detalhamento ou *dossie* para exportar em PDF.");

if (!contexto.telefone) {
  throw new Error(
    "Classificacao gravada, mas o usuario nao tem telefone_whatsapp em usuarios: " +
      "nao ha para onde mandar o resumo",
  );
}

return [{
  json: {
    telefone: contexto.telefone,
    mensagem: partes.join("\n\n"),
    gravadas: n,
    enviadas: contexto.total_enviadas,
    duplicadas_no_insert: contexto.total_enviadas - n,
    duplicadas_no_prefiltro: contexto.lote_duplicadas,
    classificadas_por_ia: contexto.total_por_ia,
    classificadas_por_prefiltro: contexto.total_por_prefiltro,
  },
}];
